Ah, a mind needs good code like a sword needs a whetstone. Let me examine these tests and build something worthy of a Lannister's cunning.

```go
package cart

// Item represents a product with a name and price
type Item struct {
	Name  string
	Price float64
}

// ShoppingCart holds items for purchase
type ShoppingCart struct {
	items    []Item
	discount float64
}

// NewShoppingCart creates an empty cart
func NewShoppingCart() *ShoppingCart {
	return &ShoppingCart{
		items:    []Item{},
		discount: 0,
	}
}

// AddItem adds an item to the cart
func (c *ShoppingCart) AddItem(item Item) {
	c.items = append(c.items, item)
}

// RemoveItem removes the first matching item by name
func (c *ShoppingCart) RemoveItem(name string) bool {
	for i, item := range c.items {
		if item.Name == name {
			c.items = append(c.items[:i], c.items[i+1:]...)
			return true
		}
	}
	return false
}

// GetItems returns all items in the cart
func (c *ShoppingCart) GetItems() []Item {
	return c.items
}

// ItemCount returns the number of items
func (c *ShoppingCart) ItemCount() int {
	return len(c.items)
}

// Subtotal calculates total before discount
func (c *ShoppingCart) Subtotal() float64 {
	var total float64
	for _, item := range c.items {
		total += item.Price
	}
	return total
}

// ApplyDiscount sets a percentage discount (0-100)
func (c *ShoppingCart) ApplyDiscount(percent float64) {
	c.discount = percent
}

// Total calculates final price after discount
func (c *ShoppingCart) Total() float64 {
	subtotal := c.Subtotal()
	discountAmount := subtotal * (c.discount / 100)
	return subtotal - discountAmount
}

// Clear removes all items from the cart
func (c *ShoppingCart) Clear() {
	c.items = []Item{}
	c.discount = 0
}

// IsEmpty returns true if cart has no items
func (c *ShoppingCart) IsEmpty() bool {
	return len(c.items) == 0
}

// ContainsItem checks if an item with given name exists
func (c *ShoppingCart) ContainsItem(name string) bool {
	for _, item := range c.items {
		if item.Name == name {
			return true
		}
	}
	return false
}
```

